/// Defines CRUD Tauri commands for given database tables. This macro creates
/// a struct that represents the data in the SQLite database, with the field
/// names matching the ones found in the database. The `id` field is
/// automatically generated by this macro and does not need to be added to the
/// input struct (it has type [`i64`]).
///
/// The struct fields must be declared in the same order as the table columns,
/// because rows are read by column index (`id` is always column 0).
///
/// ## Created functions
///
/// This macro creates five commands based on the struct name when a struct
/// is created given in the macro input. For example using the struct name
/// `Appointment` will result in the following commands being created:
///
/// ```rs
/// pub(crate) fn create_appointment(appointment: Appointment) -> Result<(), String> {}
/// pub(crate) fn read_appointment() -> Result<Vec<Appointment>, String> {}
/// pub(crate) fn read_one_appointment(id: i64) -> Result<Option<Appointment>, String> {}
/// pub(crate) fn update_appointment(with: Appointment) -> Result<(), String> {}
/// pub(crate) fn delete_appointment(id: i64) -> Result<(), String> {}
/// ```
///
/// ## Created helpers
///
/// Each struct also gets helpers that work on an open [`Connection`], so other
/// modules can reuse them (for example inside a transaction):
///
/// ```rs
/// impl Appointment {
///   pub(crate) const TABLE: &str; // "appointment"
///   pub(crate) fn from_row(row: &Row) -> Result<Self, Error> {}
///   pub(crate) fn insert(&self, connection: &Connection) -> Result<i64, Error> {} // new id
///   pub(crate) fn update(&self, connection: &Connection) -> Result<usize, Error> {} // rows changed
/// }
/// ```
///
/// ## Use
///
/// This macro is used to reduce the boilerplate code for setting up CRUD
/// operations, as well as to allow to easily define operations for newer tables
/// easier.
///
#[macro_export]
macro_rules! define_table_crud {
  (
    $(
      $(#[$attr: meta])*
      $v_outer: vis struct $table_name: ident {
        $(
          $(#[$k_comment: meta])*
          $v_inner: vis $k: ident: $t: ty
        ),+$(,)?
      }
    )+
  ) => {
    use ::{
      rusqlite::{Connection, Error, OptionalExtension, Row},
      serde::{Serialize, Deserialize},
      pastey::paste,
      ts_rs::TS
    };

    $(
      $(#[$attr])*
      #[derive(Debug, Default, Serialize, Deserialize, TS)]
      #[serde(rename_all = "camelCase")]
      #[ts(export)]
      $v_outer struct $table_name {
        pub(crate) id: i64,
        $(
          $(#[$k_comment])*
          $v_inner $k: $t,
        )+
      }

      paste! {
        impl $table_name {
          /// Name of the database table.
          pub(crate) const TABLE: &str = stringify!([<$table_name: snake>]);

          /// Column names in table order, without `id`.
          const COLUMNS: &[&str] = &[$(stringify!($k)),+];

          /// Builds the struct from a `SELECT * FROM <table>` row. Extra
          /// columns after the table's own columns are ignored.
          pub(crate) fn from_row(row: &Row<'_>) -> Result<Self, Error> {
            let mut index = 0usize;
            let id = row.get(index)?;
            $(
              index += 1;
              let $k = row.get(index)?;
            )+
            Ok(Self { id, $($k,)+ })
          }

          /// Inserts this row (ignoring `id`) and returns the new id.
          pub(crate) fn insert(&self, connection: &Connection) -> Result<i64, Error> {
            let params: Vec<String> = (1..=Self::COLUMNS.len()).map(|i| format!("?{i}")).collect();
            let command = format!(
              "INSERT INTO {} ({}) VALUES ({})",
              Self::TABLE,
              Self::COLUMNS.join(","),
              params.join(",")
            );

            connection.execute(&command, ($(&self.$k,)+))?;
            Ok(connection.last_insert_rowid())
          }

          /// Updates the row with this `id`. Returns the number of rows changed.
          pub(crate) fn update(&self, connection: &Connection) -> Result<usize, Error> {
            let fields: Vec<String> = Self::COLUMNS
              .iter()
              .enumerate()
              .map(|(i, column)| format!("{column} = ?{}", i + 1))
              .collect();
            let command = format!(
              "UPDATE {} SET {} WHERE id = {}",
              Self::TABLE,
              fields.join(", "),
              self.id
            );

            connection.execute(&command, ($(&self.$k,)+))
          }
        }

        #[tauri::command]
        pub(crate) fn [<create_ $table_name:snake>]([<$table_name:lower>]: $table_name) -> Result<(), String> {
          err_wrap(|| {
            let connection: Connection = Connection::open("soteria-db")?;
            [<$table_name:lower>].insert(&connection)?;
            connection.close().map_err(|(_, v)| v)?;
            Ok(())
          })
        }

        #[tauri::command]
        pub(crate) fn [<read_ $table_name:snake>]() -> Result<Vec<$table_name>, String> {
          err_wrap(|| {
            let connection: Connection = Connection::open("soteria-db")?;
            let mut conn_stmt = connection.prepare(&format!("SELECT * FROM {}", $table_name::TABLE))?;

            let values = conn_stmt
              .query_map([], $table_name::from_row)?
              .collect::<Result<Vec<$table_name>, Error>>()?;
            drop(conn_stmt);

            connection.close().map_err(|(_, v)| v)?;
            Ok(values)
          })
        }

        #[tauri::command]
        pub(crate) fn [<read_one_ $table_name: snake>](id: i64) -> Result<Option<$table_name>, String> {
          err_wrap(|| {
            let connection: Connection = Connection::open("soteria-db")?;

            let result = connection
              .query_row(
                &format!("SELECT * FROM {} WHERE id = ?1;", $table_name::TABLE),
                (id,),
                $table_name::from_row,
              )
              .optional()?;
            connection.close().map_err(|(_, v)| v)?;
            Ok(result)
          })
        }

        #[tauri::command]
        pub(crate) fn [<update_ $table_name: snake>](with: $table_name) -> Result<(), String> {
          err_wrap(|| {
            let connection: Connection = Connection::open("soteria-db")?;
            with.update(&connection)?;
            connection.close().map_err(|(_, v)| v)?;
            Ok(())
          })
        }

        #[tauri::command]
        pub(crate) fn [<delete_ $table_name: snake>](id: i64) -> Result<(), String> {
          err_wrap(|| {
            let connection: Connection = Connection::open("soteria-db")?;

            connection.execute(&format!("DELETE FROM {} WHERE id = ?1;", $table_name::TABLE), (id,))?;
            connection.close().map_err(|(_, v)| v)?;
            Ok(())
          })
        }
      }
    )+

    fn err_wrap<T, F>(cb: F) -> Result<T, String>
    where
      F: FnOnce() -> Result<T, Error>,
    {
      cb().map_err(|e| e.to_string())
    }
  }
}
